"url": "https://github.com/PacktPublishing/Microsoft-Intune-Cookbook/blob/main/Chapter1/create-new-user.ps1",
"title": "Create a new user",
"kind": "Configure",
"platform": "Tenant",
"summary": "Creates an Entra user account with a password profile and usage location.",
"graph": [
{
"m": "POST",
"ep": "beta/users"
}
],
"placeholders": [],
"session": [],
"lines": 33,
"lang": "powershell",
"code": "# Define the user details\n$displayname = \"User One\"\n$givenname = \"User\"\n$surname = \"One\"\n$usageLocation = \"GB\"\n$mailNickname = \"user1\"\n$password = \"PASSWORD HERE\"\n$domainname = \"DOMAIN HERE\"\n\n# Define the JSON for the new user\n$json = @\"\n{\n    \"accountEnabled\": true,\n    \"displayName\": \"$displayname\",\n    \"givenName\": \"$givenname\",\n    \"mailNickname\": \"$mailNickname\",\n    \"passwordProfile\": {\n        \"forceChangePasswordNextSignIn\": true,\n        \"password\": \"$password\"\n    },\n    \"surname\": \"$surname\",\n    \"usageLocation\": \"$usageLocation\",\n    \"userPrincipalName\": \"$mailnickname@$domainname\"\n}\n\"@\n\n# Define the URI for creating a new user\n$uri = \"https://graph.microsoft.com/beta/users\"\n\n# Send the new user details to Microsoft Graph\nWrite-Host \"Creating new user\"\nInvoke-MgGraphRequest -Method POST -Uri $uri -Body $json -ContentType \"application/json\"\nWrite-Host \"User created successfully\""
