"code": "##Set Name\n$name = \"Require App Protection Policy\"\n\n##Set URL\n$url = \"https://graph.microsoft.com/v1.0/identity/conditionalAccess/policies\"\n\n##Populate JSON\n$json = @\"\n{\n\t\"conditions\": {\n\t\t\"applications\": {\n\t\t\t\"excludeApplications\": [],\n\t\t\t\"includeApplications\": [\n\t\t\t\t\"All\"\n\t\t\t],\n\t\t\t\"includeAuthenticationContextClassReferences\": [],\n\t\t\t\"includeUserActions\": [],\n\t\t\t\"networkAccess\": null\n\t\t},\n\t\t\"clientApplications\": null,\n\t\t\"clientAppTypes\": [\n\t\t\t\"all\"\n\t\t],\n\t\t\"clients\": null,\n\t\t\"devices\": null,\n\t\t\"locations\": null,\n\t\t\"platforms\": {\n\t\t\t\"excludePlatforms\": [],\n\t\t\t\"includePlatforms\": [\n\t\t\t\t\"android\",\n\t\t\t\t\"iOS\"\n\t\t\t]\n\t\t},\n\t\t\"servicePrincipalRiskLevels\": [],\n\t\t\"signInRiskDetections\": null,\n\t\t\"signInRiskLevels\": [],\n\t\t\"times\": null,\n\t\t\"userRiskLevels\": [],\n\t\t\"users\": {\n\t\t\t\"excludeGroups\": [],\n\t\t\t\"excludeGuestsOrExternalUsers\": null,\n\t\t\t\"excludeRoles\": [],\n\t\t\t\"excludeUsers\": [],\n\t\t\t\"includeGroups\": [],\n\t\t\t\"includeGuestsOrExternalUsers\": null,\n\t\t\t\"includeRoles\": [],\n\t\t\t\"includeUsers\": [\n\t\t\t\t\"All\"\n\t\t\t]\n\t\t}\n\t},\n\t\"displayName\": \"$name\",\n\t\"grantControls\": {\n\t\t\"authenticationStrength\": null,\n\t\t\"builtInControls\": [\n\t\t\t\"compliantApplication\"\n\t\t],\n\t\t\"customAuthenticationFactors\": [],\n\t\t\"operator\": \"AND\",\n\t\t\"termsOfUse\": []\n\t},\n\t\"sessionControls\": null,\n\t\"state\": \"enabled\"\n}\n\"@\n\n##Create Policy\nWrite-Host \"Creating policy $name\"\nInvoke-MgGraphRequest -Method POST -Uri $url -Body $json -ContentType \"application/json\" -OutputType PSObject\nWrite-Host \"Policy created successfully\""
