"url": "https://github.com/PacktPublishing/Microsoft-Intune-Cookbook/blob/main/Chapter-6/assign-vpp-app.ps1",
"title": "Assign a VPP app",
"kind": "Configure",
"platform": "iOS",
"summary": "Finds an Apple Volume Purchase app and assigns it, no Apple ID needed.",
